using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;
namespace CTXD.Client.Features.Social { public sealed class VipPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;public static VipPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("VipPanel");go.transform.SetParent(host,false);var p=go.AddComponent<VipPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var blocker=LegacyUiFactory.Panel(transform,"VipBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.82f));_window=LegacyUiFactory.PixelPanel(blocker,"VipWindow",350,70,580,600,new Color(.055f,.035f,.018f,1));}async Task Refresh(){try{var v=await _api.GetVipAsync();LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"VIP BENEFITS",22,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),130,15,320,35);LegacyUiFactory.PixelButton(_window,"Close",490,18,65,27,()=>Destroy(gameObject));LegacyUiFactory.PixelLabel(_window,"VIP "+v.vipLevel+"   Free team battles: "+v.teamTimes,17,TextAnchor.MiddleCenter,Color.white,60,60,460,30);var y=105;if(v.benefits!=null)foreach(var b in v.benefits){var label="VIP"+b.vip+"-"+b.sequence+"  "+b.kind+" x"+b.amount;LegacyUiFactory.PixelLabel(_window,label,15,TextAnchor.MiddleLeft,b.available?Color.white:Color.gray,45,y,350,28);if(b.available&&!b.claimed)LegacyUiFactory.PixelButton(_window,"Claim",420,y,100,28,()=>Claim(b.vip,b.sequence));else LegacyUiFactory.PixelLabel(_window,b.claimed?"Claimed":"Locked",14,TextAnchor.MiddleCenter,b.claimed?new Color(.3f,1,.3f):Color.gray,420,y,100,28);y+=50;}}catch(Exception e){_status(e.Message);Destroy(gameObject);}}async void Claim(int vip,int sequence){try{var r=await _api.ClaimVipBenefitAsync(vip,sequence);_status("VIP reward "+r.kind+" +"+r.amount);await Refresh();}catch(Exception e){_status(e.Message);}}} }
